def check_steps(steps, initial, target, jug_sizes):
    """
    Check if a list of steps correctly measures the target amount.

    Args:
        steps: List of tuples (source, dest, amount) representing pouring actions.
        initial: Initial amount of water in the main container (e.g., 12L).
        target: The target amount to measure (e.g., 6L).
        jug_sizes: Tuple of jug sizes (e.g., (8, 5)).

    Returns:
        bool: True if steps successfully measure the target.
    """
    jug1, jug2 = jug_sizes
    j1, j2 = 0, 0  # Start with both jugs empty

    for src, dest, amount in steps:
        if src == "main":
            if initial < amount:
                return False
            initial -= amount
            if dest == "j1":
                j1 += amount
                if j1 > jug1:
                    return False
            elif dest == "j2":
                j2 += amount
                if j2 > jug2:
                    return False
        elif src == "j1":
            if j1 < amount:
                return False
            j1 -= amount
            if dest == "main":
                initial += amount
            elif dest == "j2":
                j2 += amount
                if j2 > jug2:
                    return False
        elif src == "j2":
            if j2 < amount:
                return False
            j2 -= amount
            if dest == "main":
                initial += amount
            elif dest == "j1":
                j1 += amount
                if j1 > jug1:
                    return False

    # Check if target is in either jug or main
    return j1 == target or j2 == target or initial == target

# Example usage:
steps = [
    ("main", "j1", 8),   # Fill 8L jug
    ("j1", "j2", 5),     # Pour 5L into 5L jug
    ("j2", "main", 5),   # Empty 5L jug into main
    ("j1", "j2", 3),     # Pour remaining 3L into 5L jug
    ("main", "j1", 8),   # Fill 8L jug again
    ("j1", "j2", 2),     # Pour 2L into 5L jug (which has 3L)
    ("j2", "main", 5),   # Empty 5L jug
]

print(check_steps(steps, 12, 6, (8, 5)))  # True
